  )
  expect_identical(captured[[1]], "FIMSBackend.evaluate_fixed_objective")
  expect_identical(captured[[2]], input[["parameters"]])
  expect_identical(captured[[3]], input[["data"]])
  expect_identical(captured[[4]], config)
