test_that("Julia backend serializer omits unavailable observed data entries", {
  reset_julia_backend_state()
  data <- data_big |>
    dplyr::filter(!.data$type %in% c("catch", "index", "age_comp")) |>
    FIMS::FIMSFrame()
  parameters <- FIMS::setup_default_parameters(data = data)
  julia_input <- FIMS:::prepare_julia_backend_input(parameters = parameters, data = data)

  #' @description Test that missing catch data are omitted from the Julia serializer output.
  expect_false("observed_catch" %in% names(julia_input[["data"]]))
  #' @description Test that missing index data are omitted from the Julia serializer output.
  expect_false("observed_index" %in% names(julia_input[["data"]]))
  #' @description Test that missing age-composition data are omitted from the Julia serializer output.
  expect_false("observed_age_comp" %in% names(julia_input[["data"]]))

})

test_that("Julia backend serializer preserves multiple fleets and composition streams", {
  reset_julia_backend_state()
  make_multi_fleet_data <- function(data_type) {
    dplyr::bind_rows(
      data_big,
      data_big |>
        dplyr::filter(.data$type == .env$data_type, .data$fleet == "fleet1") |>
        dplyr::mutate(fleet = "fleet2")
    ) |>
      FIMS::FIMSFrame()
  }

  catch_data <- make_multi_fleet_data("catch")
  catch_parameters <- FIMS::setup_default_parameters(data = catch_data)
  catch_input <- FIMS:::prepare_julia_backend_input(parameters = catch_parameters, data = catch_data)
  expect_equal(dim(catch_input[["data"]][["observed_catch"]]), c(get_n_years(catch_data), length(get_fleets(catch_data))))
  expect_equal(dim(catch_input[["parameters"]][["log_Fmort"]]), c(get_n_years(catch_data), length(get_fleets(catch_data))))

  index_data <- make_multi_fleet_data("index")
  index_parameters <- FIMS::setup_default_parameters(data = index_data)
  index_input <- FIMS:::prepare_julia_backend_input(parameters = index_parameters, data = index_data)
  expect_equal(dim(index_input[["data"]][["observed_index"]]), c(get_n_years(index_data), length(get_fleets(index_data))))

  agecomp_data <- make_multi_fleet_data("age_comp")
  agecomp_parameters <- FIMS::setup_default_parameters(data = agecomp_data)
  agecomp_input <- FIMS:::prepare_julia_backend_input(parameters = agecomp_parameters, data = agecomp_data)
  expect_equal(dim(agecomp_input[["data"]][["observed_age_comp"]]), c(get_n_years(agecomp_data), get_n_ages(agecomp_data), length(get_fleets(agecomp_data))))

})

test_that("Julia backend serializes maturity parameters and estimation masks", {
  data <- FIMS::FIMSFrame(data_big)
  parameters <- FIMS::setup_default_parameters(data = data) |>
    dplyr::mutate(
      estimation_type = dplyr::if_else(
        .data$module_name == "Maturity",
        "fixed_effects",
        .data$estimation_type
      )
    )
  julia_parameters <- FIMS:::as_julia_fims_parameters(parameters, data)
  julia_config <- FIMS:::as_julia_fims_model_config(parameters, data)
  parameter_names <- names(julia_parameters)
  inflection_start <- sum(purrr::map_int(
    julia_parameters[seq_len(match("maturity_inflection_point", parameter_names) - 1L)],
    length
  )) + 1L
  slope_start <- sum(purrr::map_int(
    julia_parameters[seq_len(match("maturity_slope", parameter_names) - 1L)],
    length
  )) + 1L

  expect_equal(
    julia_parameters[["maturity_inflection_point"]],
    parameters |>
      dplyr::filter(.data$module_name == "Maturity", .data$label == "inflection_point") |>
      dplyr::pull(.data$value) |>
      dplyr::first()
  )
  expect_equal(
    julia_parameters[["maturity_slope"]],
    parameters |>
      dplyr::filter(.data$module_name == "Maturity", .data$label == "slope") |>
      dplyr::pull(.data$value) |>
      dplyr::first()
  )
  expect_true(julia_config[["fixed_parameter_mask"]][inflection_start])
  expect_true(julia_config[["fixed_parameter_mask"]][slope_start])
})

test_that("Julia backend serializes scalar and age-specific proportion-female parameters", {
  data <- FIMS::FIMSFrame(data_big)
  ages <- FIMS:::get_ages(data)
  default_parameters <- FIMS::setup_default_parameters(data = data)
  scalar_parameters <- default_parameters |>
    dplyr::mutate(
      estimation_type = dplyr::if_else(
        .data$module_name == "Population" & .data$label == "proportion_female",
        "fixed_effects",
        .data$estimation_type
      )
    )
  scalar_julia_parameters <- FIMS:::as_julia_fims_parameters(scalar_parameters, data)
  scalar_config <- FIMS:::as_julia_fims_model_config(scalar_parameters, data)
  scalar_parameter_index <- sum(purrr::map_int(
    scalar_julia_parameters[seq_len(match("proportion_female", names(scalar_julia_parameters)) - 1L)],
    length
  )) + 1L
  expect_length(scalar_julia_parameters[["proportion_female"]], 1L)
  expect_true(scalar_config[["fixed_parameter_mask"]][scalar_parameter_index])

  scalar_prior <- tibble::tibble(
    module_name = "Population",
    fleet = NA_character_,
    label = "proportion_female",
    timing = NA_integer_,
    age = NA_real_,
    distribution = "Dnorm",
    mean = 0.5,
    sd = 0.1
  )
  scalar_prior_config <- FIMS:::as_julia_fims_model_config(
    scalar_parameters,
    data,
    priors = scalar_prior
  )
  expect_equal(scalar_prior_config[["parameter_prior_components"]], "proportion_female")
  expect_equal(scalar_prior_config[["parameter_prior_indices"]], 1L)
  reset_julia_backend_state()
  withr::local_options(list(FIMS.disable_julia = TRUE))
  initialized <- FIMS::initialize_fims(
    parameters = scalar_parameters, data = data,
    backend = "julia", priors = scalar_prior
  )
  expect_identical(attr(initialized, "julia_priors"), scalar_prior)

  age_specific_rows <- default_parameters |>
    dplyr::filter(
      .data$module_name == "Population",
      .data$label == "proportion_female"
    ) |>
    dplyr::slice(rep(1L, length(ages))) |>
    dplyr::mutate(
      age = .env$ages,
      value = seq(0.25, 0.75, length.out = length(.env$ages)),
      estimation_type = "fixed_effects"
    ) |>
    dplyr::arrange(dplyr::desc(.data$age))
  age_specific_parameters <- dplyr::bind_rows(
    default_parameters |>
      dplyr::filter(
        !(.data$module_name == "Population" & .data$label == "proportion_female")
      ),
    age_specific_rows
  )
  age_specific_julia_parameters <- FIMS:::as_julia_fims_parameters(
    age_specific_parameters,
    data
  )
  age_specific_config <- FIMS:::as_julia_fims_model_config(
    age_specific_parameters,
    data
  )
  proportion_indices <- sum(purrr::map_int(
    age_specific_julia_parameters[seq_len(match("proportion_female", names(age_specific_julia_parameters)) - 1L)],
    length
  )) + seq_along(ages)
  expect_equal(
    age_specific_julia_parameters[["proportion_female"]],
    age_specific_rows |>
      dplyr::arrange(.data$age) |>
      dplyr::pull(.data$value)
  )
  expect_true(all(age_specific_config[["fixed_parameter_mask"]][proportion_indices]))
  expected_age_values <- age_specific_rows |>
    dplyr::arrange(.data$age) |>
    dplyr::pull(.data$value)
  flattened_proportion_female <- FIMS:::flatten_julia_parameter_rows(
    age_specific_rows,
    estimates = list(proportion_female = expected_age_values),
    standard_errors = list(proportion_female = rep(0.05, length(ages)))
  )
  expect_equal(flattened_proportion_female[["estimated"]], expected_age_values)
  expect_equal(flattened_proportion_female[["uncertainty"]], rep(0.05, length(ages)))

  age_specific_prior <- dplyr::mutate(
    scalar_prior,
    age = ages[[2]]
  )
  age_specific_prior_config <- FIMS:::as_julia_fims_model_config(
    age_specific_parameters,
    data,
    priors = age_specific_prior
  )
  expect_equal(age_specific_prior_config[["parameter_prior_indices"]], 2L)
})

test_that("Julia backend serializes AgeSpecific selectivity by fleet and age", {
  data <- FIMS::FIMSFrame(data_big)
  fleet_names <- FIMS:::get_fleets(data)
  default_parameters <- FIMS::setup_default_parameters(data = data)
  selectivity_parameters <- purrr::map_dfr(
    fleet_names,
    \(fleet) FIMS::setup_default_Selectivity(
      data,
      fleet,
      module_type = "AgeSpecific"
    )
  )
  parameters <- dplyr::bind_rows(
    default_parameters |>
      dplyr::filter(.data$module_name != "Selectivity"),
    selectivity_parameters
  )

  julia_parameters <- FIMS:::as_julia_fims_parameters(parameters, data)
  julia_config <- FIMS:::as_julia_fims_model_config(parameters, data)
  expected_values <- matrix(
    0,
    nrow = FIMS:::get_n_ages(data),
    ncol = length(fleet_names)
  )
  expected_fixed_mask <- matrix(FALSE, nrow = nrow(expected_values), ncol = ncol(expected_values))
  for (fleet_index in seq_along(fleet_names)) {
    fleet_rows <- selectivity_parameters |>
      dplyr::filter(.data$fleet == .env$fleet_names[[fleet_index]]) |>
      dplyr::arrange(.data$age)
    expected_values[, fleet_index] <- fleet_rows[["value"]]
    expected_fixed_mask[, fleet_index] <-
      fleet_rows[["estimation_type"]] == "fixed_effects"
  }

  expect_equal(julia_config[["selectivity_types"]], rep("AgeSpecific", length(fleet_names)))
  expect_equal(julia_parameters[["logit_sel_at_age"]], as.numeric(expected_values))
  expect_equal(
    unname(tail(
      julia_config[["fixed_parameter_mask"]],
      length(expected_fixed_mask)
    )),
    unname(as.vector(expected_fixed_mask))
  )
  expect_equal(
    length(julia_config[["fixed_parameter_mask"]]),
    sum(purrr::map_int(julia_parameters, length))
  )
  flattened_selectivity <- FIMS:::flatten_julia_parameter_rows(
    selectivity_parameters,
    estimates = list(logit_sel_at_age = expected_values),
    standard_errors = list(
      logit_sel_at_age = matrix(0.1, nrow = nrow(expected_values), ncol = ncol(expected_values))
    )
  )
  expect_equal(flattened_selectivity[["estimated"]], as.numeric(expected_values))
  expect_equal(flattened_selectivity[["uncertainty"]], rep(0.1, length(expected_values)))

  prior_age <- FIMS:::get_ages(data)[[2]]
  age_prior <- tibble::tibble(
    module_name = "Selectivity",
    fleet = fleet_names[[2]],
    label = "logit_sel_at_age",
    timing = NA_integer_,
    age = prior_age,
    distribution = "Dnorm",
    mean = 0,
    sd = 1
  )
  prior_config <- FIMS:::as_julia_fims_model_config(
    parameters = parameters,
    data = data,
    priors = age_prior
  )
  expect_equal(
    prior_config[["parameter_prior_indices"]],
    2L + (2L - 1L) * FIMS:::get_n_ages(data)
  )
})

test_that("Julia backend serializes scalar and year-specific AgeSpecific layouts", {
  data <- FIMS::FIMSFrame(data_big)
  fleet_names <- FIMS:::get_fleets(data)
  ages <- FIMS:::get_ages(data)
  years <- FIMS:::get_start_year(data):FIMS:::get_end_year(data)
  default_parameters <- FIMS::setup_default_parameters(data = data) |>
    dplyr::filter(.data$module_name != "Selectivity")
  selectivity_parameters <- purrr::map_dfr(
    fleet_names,
    \(fleet) FIMS::setup_default_Selectivity(
      data,
      fleet,
      module_type = "AgeSpecific"
    )
  )

  yearly_rows <- purrr::map_dfr(seq_along(years), \(year_index) {
    selectivity_parameters |>
      dplyr::filter(.data$fleet == .env$fleet_names[[1]]) |>
      dplyr::mutate(
        timing = .env$years[[year_index]],
        value = .data$value + .env$year_index
      )
  })
  static_rows <- selectivity_parameters |>
    dplyr::filter(.data$fleet != .env$fleet_names[[1]])
  yearly_parameters <- dplyr::bind_rows(
    default_parameters,
    yearly_rows,
    static_rows
  )
  yearly_input <- FIMS:::as_julia_fims_parameters(yearly_parameters, data)
  yearly_config <- FIMS:::as_julia_fims_model_config(yearly_parameters, data)
  yearly_expected <- c(
    yearly_rows |>
      dplyr::arrange(.data$timing, .data$age) |>
      dplyr::pull(.data$value),
    static_rows |>
      dplyr::filter(.data$fleet == .env$fleet_names[[2]]) |>
      dplyr::arrange(.data$age) |>
      dplyr::pull(.data$value)
  )

  expect_equal(yearly_input[["logit_sel_at_age"]], yearly_expected)
  expect_equal(
    yearly_config[["selectivity_parameter_lengths"]],
    c(length(ages) * length(years), length(ages))
  )
  prior_year <- years[[2]]
  prior_age <- ages[[2]]
  yearly_prior <- tibble::tibble(
    module_name = "Selectivity",
    fleet = fleet_names[[1]],
    label = "logit_sel_at_age",
    timing = prior_year,
    age = prior_age,
    distribution = "Dnorm",
    mean = 0,
    sd = 1
  )
  yearly_prior_config <- FIMS:::as_julia_fims_model_config(
    yearly_parameters,
    data,
    priors = yearly_prior
  )
  expect_equal(
    yearly_prior_config[["parameter_prior_indices"]],
    (2L - 1L) * length(ages) + 2L
  )

  scalar_row <- selectivity_parameters |>
    dplyr::filter(.data$fleet == .env$fleet_names[[1]]) |>
    dplyr::slice(1L) |>
    dplyr::mutate(
      timing = NA_integer_,
      age = NA_real_,
      value = 0.25
    )
  scalar_parameters <- dplyr::bind_rows(
    default_parameters,
    scalar_row,
    static_rows
  )
  scalar_input <- FIMS:::as_julia_fims_parameters(scalar_parameters, data)
  scalar_config <- FIMS:::as_julia_fims_model_config(scalar_parameters, data)

  expect_equal(
    scalar_input[["logit_sel_at_age"]],
    c(
      0.25,
      static_rows |>
        dplyr::filter(.data$fleet == .env$fleet_names[[2]]) |>
        dplyr::arrange(.data$age) |>
        dplyr::pull(.data$value)
    )
  )
  expect_equal(
    scalar_config[["selectivity_parameter_lengths"]],
    c(1L, length(ages))
  )
})

test_that("Julia backend serializes VonBertalanffy growth parameters and masks", {
  data <- data_big |>
    dplyr::filter(.data$fleet == "fleet1") |>
    FIMS::FIMSFrame()
  default_parameters <- FIMS::setup_default_parameters(data = data)
  parameters <- dplyr::bind_rows(
    default_parameters |>
      dplyr::filter(.data$module_name != "Growth"),
    FIMS::setup_default_Growth(data, module_type = "VonBertalanffySchnute") |>
      dplyr::mutate(
        estimation_type = dplyr::if_else(
          .data$label == "mean_length_young",
          "fixed_effects",
          .data$estimation_type
        )
      )
  )
  julia_data <- FIMS:::as_julia_fims_data(data, parameters)
  julia_parameters <- FIMS:::as_julia_fims_parameters(parameters, data)
  julia_config <- FIMS:::as_julia_fims_model_config(parameters, data)

  expect_equal(julia_config[["growth_model_type"]], "VonBertalanffySchnute")
  expect_equal(
    julia_parameters[["growth_log_mean_length_young"]],
    log(parameters |>
      dplyr::filter(.data$module_name == "Growth", .data$label == "mean_length_young") |>
      dplyr::pull(.data$value))
  )
  expect_equal(julia_data[["n_lengths"]], length(julia_data[["lengths"]]))
  expect_false("age_to_length_conversion" %in% names(julia_data))

  growth_parameter_start <- sum(purrr::map_int(
    julia_parameters[seq_len(match("growth_log_mean_length_young", names(julia_parameters)) - 1L)],
    length
  )) + 1L
  expect_true(julia_config[["fixed_parameter_mask"]][growth_parameter_start])
  expect_equal(
    length(julia_config[["fixed_parameter_mask"]]),
    sum(purrr::map_int(julia_parameters, length))
  )

  prior_rows <- function(module_name, label) {
    parameters |>
      dplyr::filter(
        .data$module_name == .env$module_name,
        .data$label == .env$label
      ) |>
      dplyr::transmute(
        module_name = .data$module_name,
        fleet = .data$fleet,
        label = .data$label,
        timing = .data$timing,
        age = .data$age,
        distribution = "Dnorm",
        mean = 0,
        sd = 1
      )
  }
  growth_priors <- dplyr::bind_rows(
    prior_rows("Growth", "mean_length_young"),
    prior_rows("Growth", "length_weight_b"),
    prior_rows("Growth", "reference_age_for_length_old"),
    prior_rows("Growth", "length_at_age_sd_at_reference_ages"),
    prior_rows("Maturity", "slope")
  )
  growth_prior_config <- FIMS:::as_julia_fims_model_config(
    parameters = parameters,
    data = data,
    priors = growth_priors
  )
  expect_equal(
    growth_prior_config[["parameter_prior_components"]],
    c(
      "growth_log_mean_length_young",
      "growth_log_length_weight_b",
      "growth_reference_age_old",
      "growth_log_length_sd_at_young",
      "growth_log_length_sd_at_old",
      "maturity_slope"
    )
  )
  expect_equal(
    growth_prior_config[["parameter_prior_transforms"]],
    c("exp", "exp", "identity", "exp", "exp", "identity")
  )

  delta_labels <- c(
    "log_sd_mean_length_young",
    "log_sd_mean_length_old",
    "log_sd_growth_coefficient",
    "mean_length_young_mean_length_old_logit_corr",
    "mean_length_young_growth_coefficient_logit_corr",
    "mean_length_old_growth_coefficient_logit_corr"
  )
  delta_growth_parameters <- FIMS::setup_default_Growth(
    data,
    module_type = "VonBertalanffySchnute"
  ) |>
    dplyr::filter(.data$label != "length_at_age_sd_at_reference_ages") |>
    dplyr::bind_rows(purrr::map_dfr(delta_labels, \(label) {
      FIMS::setup_default_Growth(data, module_type = "VonBertalanffySchnute") |>
        dplyr::slice(1L) |>
        dplyr::mutate(
          label = .env$label,
          age = NA_real_,
          value = 0
        )
    }))
  delta_parameters <- dplyr::bind_rows(
    parameters |>
      dplyr::filter(.data$module_name != "Growth"),
    delta_growth_parameters
  )
  delta_priors <- delta_parameters |>
    dplyr::filter(
      .data$module_name == "Growth",
      .data$label %in% .env$delta_labels
    ) |>
    dplyr::transmute(
      module_name = .data$module_name,
      fleet = .data$fleet,
      label = .data$label,
      timing = .data$timing,
      age = .data$age,
      distribution = "Dnorm",
      mean = 0,
      sd = 1
    )
  delta_prior_config <- FIMS:::as_julia_fims_priors(
    priors = delta_priors,
    parameters = delta_parameters,
    data = data
  )
  expect_equal(
    delta_prior_config[["parameter_prior_components"]],
    paste0("growth_", delta_labels)
  )
  expect_equal(
    delta_prior_config[["parameter_prior_transforms"]],
    rep("identity", length(delta_labels))
  )
})

test_that("Julia backend serializes fleet-specific VonBertalanffy length bins", {
  fleet_names <- FIMS:::get_fleets(FIMS::FIMSFrame(data_big))
  skip_if(length(fleet_names) < 2L)
  data <- data_big |>
    dplyr::mutate(
      length = dplyr::if_else(
        .data$type == "length_comp" & .data$fleet == fleet_names[[2]],
        .data$length + 1,
        .data$length
      )
    ) |>
    FIMS::FIMSFrame()
  default_parameters <- FIMS::setup_default_parameters(data = data)
  parameters <- dplyr::bind_rows(
    default_parameters |>
      dplyr::filter(.data$module_name != "Growth"),
    FIMS::setup_default_Growth(data, module_type = "VonBertalanffySchnute")
  )

  julia_data <- FIMS:::as_julia_fims_data(data, parameters)
  raw_data <- FIMS:::get_data(data)
  expected_bins <- lapply(fleet_names, function(fleet) {
    sort(unique(raw_data$length[
      raw_data$type == "length_comp" & raw_data$fleet == fleet
    ]))
  })

  expect_equal(
    julia_data[["n_lengths_by_fleet"]],
    unname(lengths(expected_bins))
  )
  expect_equal(
    julia_data[["lengths_by_fleet"]],
    unname(vapply(
      expected_bins,
      function(bins) {
        c(bins, rep(0, julia_data[["n_lengths"]] - length(bins)))
      },
      numeric(julia_data[["n_lengths"]])
    ))
  )
  observed_length_comp <- julia_data[["observed_length_comp"]]
  expect_equal(
    dim(observed_length_comp),
    c(
      FIMS:::get_n_years(data),
      julia_data[["n_lengths"]],
      length(fleet_names)
    )
  )
  for (fleet_index in seq_along(fleet_names)) {
    fleet_bin_indices <- match(expected_bins[[fleet_index]], julia_data[["lengths"]])
    absent_bin_indices <- setdiff(
      seq_len(julia_data[["n_lengths"]]),
      fleet_bin_indices
    )
    expect_true(any(observed_length_comp[, fleet_bin_indices, fleet_index] != -999))
    fleet_observation_years <- unique(raw_data$timing[
      raw_data$type == "length_comp" &
        raw_data$fleet == fleet_names[[fleet_index]]
    ])
    sampled_year_indices <- fleet_observation_years -
      FIMS:::get_start_year(data) + 1L
    expect_true(all(
      observed_length_comp[sampled_year_indices, absent_bin_indices, fleet_index] == 0
    ))
  }
})

test_that("Julia backend respects explicit fleet bins without compositions", {
  fleet_names <- FIMS:::get_fleets(FIMS::FIMSFrame(data_big))
  skip_if(length(fleet_names) < 2L)
  explicit_bins <- lapply(seq_along(fleet_names), function(fleet_index) {
    seq(fleet_index, by = 50, length.out = 5)
  })
  length_bin_data <- purrr::map2_dfr(
    fleet_names,
    explicit_bins,
    function(fleet, bins) {
      fleet_unit <- unique(
        data_big$unit[which(data_big$fleet == fleet)]
      )[1]
      tibble::tibble(
        type = "length_bin",
        fleet = fleet,
        age = NA_real_,
        length = bins,
        observed = NA_real_,
        unit = fleet_unit,
        timing = NA_real_,
        uncertainty = NA_character_
      )
    }
  )
  data <- data_big |>
    dplyr::filter(!.data$type %in% c(
      "length_comp",
      "age_to_length_conversion",
      "length_bin"
    )) |>
    dplyr::bind_rows(length_bin_data) |>
    FIMS::FIMSFrame()
  default_parameters <- FIMS::setup_default_parameters(data = data)
  parameters <- dplyr::bind_rows(
    default_parameters |>
      dplyr::filter(.data$module_name != "Growth"),
    FIMS::setup_default_Growth(data, module_type = "VonBertalanffySchnute")
  )

  julia_data <- FIMS:::as_julia_fims_data(data, parameters)
  expected_length_bins <- matrix(
    0,
    nrow = julia_data[["n_lengths"]],
    ncol = length(fleet_names)
  )
  for (fleet_index in seq_along(fleet_names)) {
    expected_length_bins[
      seq_along(explicit_bins[[fleet_index]]),
      fleet_index
    ] <- explicit_bins[[fleet_index]]
  }

  expect_equal(
    julia_data[["lengths_by_fleet"]],
    expected_length_bins
  )
  expect_equal(
    julia_data[["n_lengths_by_fleet"]],
    rep(length(explicit_bins[[1]]), length(fleet_names))
  )
})

test_that("Julia backend serializes VonBertalanffy delta-method variability", {
  data <- data_big |>
    dplyr::filter(.data$fleet == "fleet1") |>
    FIMS::FIMSFrame()
  default_parameters <- FIMS::setup_default_parameters(data = data)
  growth_parameters <- FIMS::setup_default_Growth(
    data,
    module_type = "VonBertalanffySchnute"
  ) |>
    dplyr::filter(.data$label != "length_at_age_sd_at_reference_ages")
  delta_method_labels <- c(
    "log_sd_mean_length_young",
    "log_sd_mean_length_old",
    "log_sd_growth_coefficient",
    "mean_length_young_mean_length_old_logit_corr",
    "mean_length_young_growth_coefficient_logit_corr",
    "mean_length_old_growth_coefficient_logit_corr"
  )
  delta_method_values <- c(log(0.1), log(0.1), log(0.02), 0.1, -0.2, 0.3)
  delta_method_rows <- growth_parameters[rep(1L, length(delta_method_labels)), ]
  delta_method_rows[["label"]] <- delta_method_labels
  delta_method_rows[["value"]] <- delta_method_values
  delta_method_rows[["estimation_type"]] <- c("fixed_effects", rep("constant", 5L))
  if ("age" %in% names(delta_method_rows)) {
    delta_method_rows[["age"]] <- NA_real_
  }
  parameters <- dplyr::bind_rows(
    default_parameters |>
      dplyr::filter(.data$module_name != "Growth"),
    growth_parameters,
    delta_method_rows
  )

  julia_parameters <- FIMS:::as_julia_fims_parameters(parameters, data)
  julia_config <- FIMS:::as_julia_fims_model_config(parameters, data)
  expect_equal(
    julia_parameters[["growth_log_sd_mean_length_young"]],
    log(0.1)
  )
  expect_equal(
    julia_parameters[["growth_mean_length_young_growth_coefficient_logit_corr"]],
    -0.2
  )
  expect_false("growth_log_length_sd_at_young" %in% names(julia_parameters))
  expect_equal(
    length(julia_config[["fixed_parameter_mask"]]),
    sum(purrr::map_int(julia_parameters, length))
  )
  delta_sd_component_index <- match(
    "growth_log_sd_mean_length_young",
    names(julia_parameters)
  )
  delta_sd_index <- sum(purrr::map_int(
    julia_parameters[seq_len(delta_sd_component_index - 1L)],
    length
  )) + 1L
  expect_true(julia_config[["fixed_parameter_mask"]][delta_sd_index])

  flat_parameter <- FIMS:::flatten_julia_parameter_rows(
    delta_method_rows[1, , drop = FALSE],
    estimates = list(growth_log_sd_mean_length_young = log(0.1)),
    standard_errors = list(growth_log_sd_mean_length_young = 0.2)
  )
  expect_equal(flat_parameter[["estimated"]], log(0.1))
  expect_equal(flat_parameter[["uncertainty"]], 0.2)
})

test_that("Julia backend config preserves normal catch and lognormal index likelihoods", {
  data <- data_big |>
    dplyr::mutate(
      uncertainty = dplyr::if_else(
        .data$type == "catch",
        paste0(
          "~ dnorm(mean = catch_expected, sd = ",
          .data$timing - min(data_big[["timing"]][data_big[["type"]] == "catch"]) + 2,
          ")"
        ),
        as.character(.data$uncertainty)
      )
    ) |>
    FIMS::FIMSFrame()
  parameters <- FIMS::setup_default_parameters(data = data)
  config <- FIMS:::as_julia_fims_model_config(parameters = parameters, data = data)

  expect_equal(config[["catch_distribution"]], "dnorm")
  expect_equal(dim(config[["catch_sigma"]]), c(get_n_years(data), length(get_fleets(data))))
  catch_fleet <- match("fleet1", get_fleets(data))
  expect_equal(config[["catch_sigma"]][1, catch_fleet], 2)
  expect_equal(config[["catch_sigma"]][2, catch_fleet], 3)
  expect_equal(config[["index_distribution"]], "dlnorm")
  expect_equal(dim(config[["index_sigma"]]), c(get_n_years(data), length(get_fleets(data))))
  expect_true(all(config[["index_sigma"]] > 0))
  expect_true(config[["recruitment_process_active"]])

  slope_prior <- tibble::tibble(
    module_name = "Selectivity",
    fleet = "fleet1",
    label = "slope",
    timing = NA_integer_,
    age = NA_real_,
    distribution = "Dnorm",
    mean = 1.5,
    sd = 3
  )
  prior_config <- FIMS:::as_julia_fims_model_config(
    parameters = parameters,
    data = data,
    priors = slope_prior
  )
  expect_equal(prior_config[["parameter_prior_components"]], "slope")
  expect_equal(prior_config[["parameter_prior_indices"]], 1L)
  expect_equal(prior_config[["parameter_prior_distributions"]], "dnorm")
  expect_equal(prior_config[["parameter_prior_means"]], 1.5)
  expect_equal(prior_config[["parameter_prior_sds"]], 3)

  testthat::local_mocked_bindings(
    initialize_julia_backend = function(...) FALSE,
    .package = "FIMS"
  )
  initialized <- FIMS::initialize_fims(
    parameters = parameters,
    data = data,
    backend = "julia",
    priors = slope_prior
  )
  expect_equal(
    attr(initialized, "julia_model_config")[["parameter_prior_components"]],
    "slope"
  )
  expect_error(
    FIMS:::as_julia_fims_model_config(
      parameters = parameters,
      data = data,
      priors = dplyr::mutate(slope_prior, label = "unknown_parameter")
    ),
    regexp = "identify exactly one parameter row"
  )
  expect_error(
    FIMS:::as_julia_fims_model_config(
      parameters = parameters |>
        dplyr::mutate(
          distribution_type = dplyr::if_else(
            .data$module_name == "Selectivity" & .data$label == "slope",
            "prior",
            .data$distribution_type
          )
        ),
      data = data
    ),
    regexp = "must be supplied with the.*priors"
  )

  lognormal_process_parameters <- parameters |>
    dplyr::mutate(
      distribution = dplyr::if_else(
        .data$module_name == "Recruitment" & .data$label == "log_devs",
        "Dlnorm",
        as.character(.data$distribution)
      )
    )
  lognormal_process_config <- FIMS:::as_julia_fims_model_config(
    parameters = lognormal_process_parameters,
    data = data
  )
  expect_equal(lognormal_process_config[["recruitment_process_distribution"]], "dlnorm")

  unsupported_composition_data <- data_big |>
    dplyr::mutate(
      uncertainty = dplyr::if_else(
        .data$type == "age_comp",
        "~ dnorm(mean = age_comp_expected, sd = 0.1)",
        as.character(.data$uncertainty)
      )
    ) |>
    FIMS::FIMSFrame()
  unsupported_composition_parameters <- FIMS::setup_default_parameters(
    data = unsupported_composition_data
  )
  expect_error(
    FIMS:::as_julia_fims_model_config(
      parameters = unsupported_composition_parameters,
      data = unsupported_composition_data
    ),
    regexp = "only.*dmultinom"
  )

  unsupported_selectivity_parameters <- parameters |>
    dplyr::mutate(
      module_type = dplyr::if_else(
        .data$module_name == "Selectivity",
        "Logistic3D",
        .data$module_type
      )
    )
  expect_error(
    FIMS:::as_julia_fims_model_config(
      parameters = unsupported_selectivity_parameters,
      data = data
    ),
    regexp = "does not support.*Selectivity"
  )

  mixed_catch_data <- dplyr::bind_rows(
    data_big |>
      dplyr::mutate(
        uncertainty = dplyr::if_else(
          .data$type == "catch",
          "~ dnorm(mean = catch_expected, sd = 0.1)",
          as.character(.data$uncertainty)
        )
      ),
    data_big |>
      dplyr::filter(.data$type == "catch", .data$fleet == "fleet1") |>
      dplyr::mutate(
        fleet = "fleet2",
        uncertainty = "~ dlnorm(meanlog = log_catch_expected, sdlog = 0.2)"
      )
  ) |>
    FIMS::FIMSFrame()
  mixed_catch_parameters <- FIMS::setup_default_parameters(data = mixed_catch_data)
  mixed_catch_config <- FIMS:::as_julia_fims_model_config(
    parameters = mixed_catch_parameters,
    data = mixed_catch_data
  )
  mixed_catch_families <- mixed_catch_config[["catch_distribution"]]
  expect_equal(dim(mixed_catch_families), dim(mixed_catch_config[["catch_sigma"]]))
  expect_equal(mixed_catch_families[1, match("fleet1", get_fleets(mixed_catch_data))], "dnorm")
  expect_equal(mixed_catch_families[1, match("fleet2", get_fleets(mixed_catch_data))], "dlnorm")

  no_process_parameters <- parameters |>
    dplyr::mutate(
      distribution_type = dplyr::if_else(
        .data$module_name == "Recruitment" & .data$label == "log_devs",
        NA_character_,
        .data$distribution_type
      ),
      distribution = dplyr::if_else(
        .data$module_name == "Recruitment" & .data$label == "log_devs",
        NA_character_,
        .data$distribution
      )
    )
  no_process_config <- FIMS:::as_julia_fims_model_config(
    parameters = no_process_parameters,
    data = data
  )
  expect_false(no_process_config[["recruitment_process_active"]])

  partial_process_parameters <- parameters |>
    dplyr::group_by(.data$module_name, .data$label) |>
    dplyr::mutate(
      distribution_type = dplyr::if_else(
        .data$module_name == "Recruitment" &
          .data$label == "log_devs" &
          dplyr::row_number() == 1L,
        NA_character_,
        .data$distribution_type
      ),
      distribution = dplyr::if_else(
        .data$module_name == "Recruitment" &
          .data$label == "log_devs" &
          dplyr::row_number() == 1L,
        NA_character_,
        .data$distribution
      )
    ) |>
    dplyr::ungroup()
  expect_error(
    FIMS:::as_julia_fims_model_config(partial_process_parameters, data),
    regexp = "distribution for every"
  )
  constant_process_parameters <- partial_process_parameters |>
    dplyr::mutate(
      estimation_type = dplyr::if_else(
        .data$module_name == "Recruitment" & .data$label == "log_devs" &
          is.na(.data$distribution),
        "constant",
        .data$estimation_type
      )
    )
  constant_process_config <- FIMS:::as_julia_fims_model_config(
    constant_process_parameters, data
  )
  expect_true(constant_process_config[["recruitment_process_active"]])
  expect_equal(
    constant_process_config[["recruitment_process_distribution"]], "dnorm"
  )

  log_r_parameters <- parameters |>
    dplyr::filter(.data$label != "log_devs") |>
    dplyr::bind_rows(
      parameters |>
        dplyr::filter(.data$label == "log_devs") |>
        dplyr::mutate(label = "log_r")
    )
  log_r_config <- FIMS:::as_julia_fims_model_config(log_r_parameters, data)
  log_r_input <- FIMS:::as_julia_fims_parameters(log_r_parameters, data)
  expect_equal(log_r_config[["recruitment_process_mode"]], "log_r")
  expect_equal(length(log_r_input[["log_r"]]), get_n_years(data) - 1L)

  scalar_log_sd_parameters <- parameters |>
    dplyr::filter(.data$label != "log_sd") |>
    dplyr::bind_rows(
      parameters |>
        dplyr::filter(.data$module_name == "Recruitment", .data$label == "log_sd") |>
        dplyr::slice(1L) |>
        dplyr::mutate(value = log(0.1), estimation_type = "fixed_effects")
    )
  scalar_log_sd_input <- FIMS:::as_julia_fims_parameters(
    scalar_log_sd_parameters,
    data
  )
  expect_length(scalar_log_sd_input[["log_sd"]], 1L)
  expect_equal(scalar_log_sd_input[["log_sd"]], log(0.1))

  vector_log_sd_parameters <- parameters |>
    dplyr::filter(.data$label != "log_sd") |>
    dplyr::bind_rows(
      parameters |>
        dplyr::filter(.data$module_name == "Recruitment", .data$label == "log_sd") |>
        dplyr::slice(rep(1L, get_n_years(data) - 1L)) |>
        dplyr::mutate(
          value = log(seq_len(get_n_years(data) - 1L) / 10),
          timing = seq.int(get_start_year(data) + 1L, get_end_year(data)),
          estimation_type = "fixed_effects"
        )
    )
  vector_log_sd_config <- FIMS:::as_julia_fims_model_config(
    vector_log_sd_parameters,
    data
  )
  vector_log_sd_input <- FIMS:::as_julia_fims_parameters(
    vector_log_sd_parameters,
    data
  )
  log_sd_start <- sum(purrr::map_int(
    vector_log_sd_input[seq_len(match("log_sd", names(vector_log_sd_input)) - 1L)],
    length
  )) + 1L
  log_sd_indices <- seq.int(
    log_sd_start,
    length.out = length(vector_log_sd_input[["log_sd"]])
  )
  expect_equal(length(vector_log_sd_input[["log_sd"]]), get_n_years(data) - 1L)
  expect_true(all(vector_log_sd_config[["fixed_parameter_mask"]][log_sd_indices]))
  expect_equal(
    length(vector_log_sd_config[["fixed_parameter_mask"]]),
    sum(purrr::map_int(vector_log_sd_input, length))
  )

  invalid_log_sd_parameters <- parameters |>
    dplyr::filter(.data$label != "log_sd") |>
    dplyr::bind_rows(
      parameters |>
        dplyr::filter(.data$module_name == "Recruitment", .data$label == "log_sd") |>
        dplyr::slice(rep(1L, 2L)) |>
        dplyr::mutate(timing = seq.int(get_start_year(data) + 1L, length.out = 2L))
    )
  expect_error(
    FIMS:::as_julia_fims_model_config(invalid_log_sd_parameters, data),
    regexp = "must contain one value"
  )
})

test_that("Julia backend fit_fims returns a FIMSFit object through the Julia bridge", {
  reset_julia_backend_state()
  withr::local_options(list(
    FIMS.disable_julia = TRUE,
    rlib_message_verbosity = "verbose"
  ))
  captured_optimizer_config <- NULL
  mock_gradient_value <- 0
  mock_pd_hessian <- TRUE
  data <- FIMS::FIMSFrame(data_big)
  parameters <- FIMS::setup_default_parameters(data = data)
  result <- FIMS::initialize_fims(parameters = parameters, data = data, backend = "julia")
  julia_input <- attr(result, "julia_input")
  parameter_lengths <- purrr::map_int(julia_input[["parameters"]], length)
  flattened_parameter_count <- sum(parameter_lengths)
  n_years <- get_n_years(data)
  n_report_years <- n_years + 1L
  n_ages <- get_n_ages(data)
  n_fleets <- length(get_fleets(data))
  n_lengths <- get_n_lengths(data)
  weights_at_age <- julia_input[["data"]][["weights_at_age"]]
  if (NROW(weights_at_age) == n_years) {
    weights_at_age <- rbind(weights_at_age, weights_at_age[n_years, , drop = FALSE])
  }
  unfished_numbers_at_age <- matrix(
    seq_len(n_report_years * n_ages),
    nrow = n_report_years,
    ncol = n_ages,
    byrow = TRUE
  )
  mocked_report <- list(
    numbers_at_age = matrix(1, nrow = n_report_years, ncol = n_ages),
    catch_numbers_at_age = matrix(0.1, nrow = n_years, ncol = n_ages),
    biomass = rep(1, n_report_years),
    spawning_biomass = rep(0.5, n_report_years),
    expected_recruitment = rep(1, n_report_years),
    unfished_numbers_at_age = unfished_numbers_at_age,
    unfished_biomass = rep(2, n_report_years),
    unfished_spawning_biomass = rep(1, n_report_years),
    spawning_biomass_ratio = rep(0.5, n_report_years),
    mortality_F = matrix(0.1, nrow = n_years, ncol = n_ages),
    mortality_M = matrix(0.2, nrow = n_years, ncol = n_ages),
    mortality_Z = matrix(0.3, nrow = n_years, ncol = n_ages),
    proportion_mature_at_age = matrix(0.5, nrow = n_report_years, ncol = n_ages),
    weights_at_age = weights_at_age,
    sum_selectivity = matrix(1, nrow = n_years, ncol = n_ages),
    total_catch_numbers = rep(1, n_years),
    total_catch_weight = rep(1, n_years),
    catch_expected = rep(1, n_years),
    index_expected = rep(0.5, n_years),
    catch_expected_by_fleet = matrix(1, nrow = n_years, ncol = n_fleets),
    index_expected_by_fleet = matrix(0.5, nrow = n_years, ncol = n_fleets),
    catch_numbers_by_fleet = matrix(1, nrow = n_years, ncol = n_fleets),
    index_numbers_by_fleet = matrix(1, nrow = n_years, ncol = n_fleets),
    catch_weight_at_age_by_fleet = array(0.1, dim = c(n_years, n_ages, n_fleets)),
    index_weight_at_age_by_fleet = array(0.1, dim = c(n_years, n_ages, n_fleets)),
    catch_numbers_at_age_by_fleet = array(0.1, dim = c(n_years, n_ages, n_fleets)),
    index_numbers_at_age_by_fleet = array(0.1, dim = c(n_years, n_ages, n_fleets)),
    agecomp_expected = array(1 / n_ages, dim = c(n_years, n_ages, n_fleets)),
    lengthcomp_expected = array(1 / n_lengths, dim = c(n_years, n_lengths, n_fleets)),
    nll_components = c(2.5, 10),
    growth_derived_mean_WAA_by_fleet = array(
      seq_len(n_years * n_ages * n_fleets),
      dim = c(n_years, n_ages, n_fleets)
    ),
    age_to_length_conversion_derived_used = c(1, rep(0, n_fleets - 1L))
  )

  testthat::local_mocked_bindings(
   initialize_julia_backend = function(...) TRUE,
   assign_julia_backend_input = function(...) invisible(TRUE),
   fit_julia_backend_model = function(julia_input, model_config) {
     captured_optimizer_config <<- model_config
     compute_standard_errors <- isTRUE(model_config[["compute_standard_errors"]])
     list(
       estimates = julia_input[["parameters"]],
       standard_errors = purrr::imap(
         julia_input[["parameters"]],
         \(value, name) rep(if (compute_standard_errors) 0.1 else NA_real_, length(value))
       ),
       report_standard_errors = if (compute_standard_errors) {
         list(
           biomass = rep(0.25, n_report_years),
           mortality_F = matrix(seq_len(n_years * n_ages), nrow = n_years),
           unfished_numbers_at_age = matrix(
             0.3,
             nrow = n_report_years,
             ncol = n_ages
           ),
           unfished_biomass = rep(0.35, n_report_years),
           unfished_spawning_biomass = rep(0.4, n_report_years),
           spawning_biomass_ratio = rep(0.45, n_report_years),
           catch_expected_by_fleet = matrix(
             seq_len(n_years * n_fleets),
             nrow = n_years,
             ncol = n_fleets
           )
         )
       } else {
         list()
       },
       report_standard_errors_flat = if (compute_standard_errors) {
         rep(0.25, 2L)
       } else {
         numeric()
       },
       report_values = c(1, 2),
       report_value_names = c("mock_report_1", "mock_report_2"),
       report_covariance = if (isTRUE(model_config[["compute_report_covariance"]])) {
         diag(2L)
       } else {
         NULL
       },
       covariance = diag(0.01, flattened_parameter_count),
       fixed_parameters = purrr::flatten_dbl(julia_input[["parameters"]])[
         as.logical(model_config[["fixed_parameter_mask"]])
       ],
       pd_hessian = mock_pd_hessian,
       gradient = rep(mock_gradient_value, flattened_parameter_count),
       hessian = diag(flattened_parameter_count),
       fixed_hessian = diag(sum(model_config[["fixed_parameter_mask"]])),
       nll = 12.5,
       joint_nll = 13.5,
       convergence = TRUE,
       convergence_code = "SUCCESS",
       iterations = 4L,
       report = mocked_report
     )
   },
   .package = "FIMS"
  )

  fit <- FIMS::fit_fims(
    result,
    optimize = TRUE,
    number_of_loops = 2,
    control = list(eval.max = 17, iter.max = 23, trace = 1)
  )

  expect_equal(captured_optimizer_config[["optimizer_max_evaluations"]], 17L)
  expect_equal(captured_optimizer_config[["optimizer_max_iterations"]], 23L)
  expect_true(captured_optimizer_config[["optimizer_trace"]])
  expect_equal(captured_optimizer_config[["optimizer_restarts"]], 2L)
  expect_error(
    FIMS::fit_fims(result, control = list(unsupported = 1)),
    regexp = "does not support optimizer control fields"
  )
  for (invalid_control in list(
    list(10),
    list(iter.max = 10, iter.max = 20),
    stats::setNames(list(10), NA_character_)
  )) {
    expect_error(
      FIMS::fit_fims(result, control = invalid_control),
      regexp = "unique, non-empty names"
    )
  }
  expect_error(
    FIMS::fit_fims(result, control = list(iter.max = 2^31)),
    regexp = "must be a positive integer"
  )
  expect_error(
    FIMS::fit_fims(result, number_of_loops = 2^31),
    regexp = "must be a non-negative integer"
  )
  #' @description Test that the Julia backend fit bridge now returns a FIMSFit object.
  expect_s4_class(fit, "FIMSFit")
  #' @description Test that the Julia backend fit bridge preserves backend metadata in the fit input.
  expect_equal(attr(FIMS::get_input(fit), "backend"), "julia")
  expect_type(FIMS::get_model_output(fit), "character")
  expect_equal(
    jsonlite::fromJSON(FIMS::get_model_output(fit))[["backend"]],
    "julia"
  )
  #' @description Test that the Julia backend fit bridge records an optimizer result.
  expect_equal(FIMS::get_opt(fit)[["convergence"]], 0L)
  #' @description Test that the Julia backend fit bridge exposes the Julia report jnll through get_report().
  expect_equal(FIMS::get_report(fit)[["jnll"]], 13.5)
  expect_equal(FIMS::get_report(fit)[["nll_components"]], c(2.5, 10))
  #' @description Test that Julia backend reports include the mortality and fleet-derived quantities used by FIMS summaries.
  expect_true(all(c("mortality_F", "mortality_M", "mortality_Z", "total_catch_numbers") %in% names(FIMS::get_report(fit))))
  #' @description Test that Julia backend reports preserve both recruitment process parameterizations.
  expect_true(all(c("log_recruit_dev", "log_r") %in% names(FIMS::get_report(fit))))
  expect_length(FIMS::get_report(fit)[["catch_expected"]], n_fleets)
  expect_equal(
    FIMS::get_report(fit)[["catch_expected"]][[1]],
    rep(1, n_years)
  )
  expect_equal(
    FIMS::get_report(fit)[["catch_numbers_at_age"]][[1]],
    rep(0.1, n_years * n_ages)
  )
  expect_equal(
    FIMS::get_report(fit)[["index_numbers_at_age"]][[2]],
    rep(0.1, n_years * n_ages)
  )
  expect_equal(
    FIMS::get_report(fit)[["agecomp_expected"]][[2]],
    rep(1 / n_ages, n_years * n_ages)
  )
  expect_equal(
    FIMS::get_report(fit)[["growth_derived_mean_WAA"]][[1]],
    as.numeric(t(matrix(
      seq_len(n_years * n_ages),
      nrow = n_years,
      ncol = n_ages
    )))
  )
  expect_length(
    FIMS::get_report(fit)[["growth_derived_mean_WAA"]][[2]],
    0L
  )
  expect_equal(FIMS::get_report(fit)[["age_to_length_conversion_derived_used"]][[1]], 1)
  expect_equal(FIMS::get_report(fit)[["age_to_length_conversion_derived_used"]][[2]], 0)
  expect_true(all(vapply(
    FIMS::get_report(fit)[["age_to_length_conversion_derived"]],
    length,
    integer(1)
  ) == 0L))
  #' @description Test that Julia backend fits produce estimate rows for catch and mortality quantities.
  expect_true(all(c("catch_expected", "mortality_F") %in% FIMS::get_estimates(fit)[["label"]]))
  expect_true(all(c(
    "unfished_numbers_at_age",
    "unfished_biomass",
    "unfished_spawning_biomass",
    "spawning_biomass_ratio"
  ) %in% FIMS::get_estimates(fit)[["label"]]))
  expect_equal(
    FIMS::get_estimates(fit) |>
      dplyr::filter(.data$label == "biomass") |>
      dplyr::pull(.data$uncertainty),
    rep(0.25, n_report_years)
  )
  expect_length(
    FIMS::get_report(fit)[["spawning_biomass"]][[1]],
    n_report_years
  )
  expect_equal(
    FIMS::get_report(fit)[["unfished_numbers_at_age"]][[1]],
    as.numeric(t(unfished_numbers_at_age))
  )
  expect_equal(
    nrow(FIMS::get_estimates(fit) |>
      dplyr::filter(.data$label == "numbers_at_age")),
    n_report_years * n_ages
  )
  expect_equal(
    FIMS::get_estimates(fit) |>
    dplyr::filter(.data$label == "spawning_biomass_ratio") |>
    dplyr::pull(.data$uncertainty),
    rep(0.45, n_report_years)
  )
  expect_equal(
    FIMS::get_estimates(fit) |>
    dplyr::filter(.data$label == "unfished_numbers_at_age") |>
    dplyr::pull(.data$estimated),
    as.numeric(t(unfished_numbers_at_age))
  )
  expect_equal(
    FIMS::get_estimates(fit) |>
      dplyr::filter(.data$label == "mortality_F") |>
      dplyr::pull(.data$uncertainty),
    as.numeric(t(matrix(
      seq_len(n_years * n_ages),
      nrow = n_years
    )))
  )
  expect_equal(
    FIMS::get_estimates(fit) |>
      dplyr::filter(
        .data$label == "catch_expected",
        .data$fleet == get_fleets(data)[[1]]
      ) |>
      dplyr::pull(.data$uncertainty),
    seq_len(n_years)
  )
  #' @description Test that Julia backend fits support backend-neutral glance summaries.
  expect_equal(generics::glance(fit)[["marginal_nll"]], 12.5  )
  expect_s3_class(FIMS::get_sdreport(fit), "sdreport")
  expect_equal(
    unname(summary(FIMS::get_sdreport(fit), "fixed")[, "Std. Error"]),
    rep(0.1, FIMS::get_number_of_parameters(fit)[["fixed_effects"]])
  )
  expect_equal(FIMS::get_sdreport(fit)[["cov"]], NA_real_)
  fit_with_covariance <- FIMS::fit_fims(
    result,
    optimize = TRUE,
    getReportCovariance = TRUE
  )
  expect_equal(
    FIMS::get_sdreport(fit_with_covariance)[["cov"]],
    diag(2L)
  )
  fit_without_saved_sd <- FIMS::fit_fims(result, optimize = TRUE, save_sd = FALSE)
  expect_length(FIMS::get_sdreport(fit_without_saved_sd), 0L)
  expect_true(all(
    FIMS::get_estimates(fit_without_saved_sd) |>
      dplyr::filter(.data$label == "biomass") |>
      dplyr::pull(.data$uncertainty) == 0.25
  ))

  fit_without_sd <- FIMS::fit_fims(result, optimize = TRUE, get_sd = FALSE)
  expect_true(all(is.na(FIMS::get_estimates(fit_without_sd)[["uncertainty"]])))

  mock_gradient_value <- 0.02
  expect_warning(FIMS::fit_fims(result), "Optimization resulted in high gradients")
  mock_gradient_value <- 2
  expect_warning(FIMS::fit_fims(result), "Maximum absolute gradient")
  mock_gradient_value <- 0
  mock_pd_hessian <- FALSE
  expect_warning(FIMS::fit_fims(result), "Standard error calculations failed convergence checks")
  mock_pd_hessian <- TRUE

  testthat::local_mocked_bindings(
    evaluate_julia_backend_model = function(...) list(
      nll = 13.5, report = mocked_report
    ),
    .package = "FIMS"
  )
  initial_fit <- FIMS::fit_fims(result, optimize = FALSE, get_sd = FALSE)
  expect_length(
    FIMS::get_obj(initial_fit)[["par"]],
    sum(attr(result, "julia_model_config")[["fixed_parameter_mask"]])
  )
  expect_true(all(is.na(FIMS::get_gradient(initial_fit))))
  expect_equal(FIMS::get_report(initial_fit)[["jnll"]], 13.5)

})

